package '航空涡扇发动机功能架构概念基线' {
    doc /* 航空涡扇发动机功能架构概念基线：方案阶段功能架构概念基线总纲 */

    package '需求' {
        doc /* 航空涡扇发动机整车级 IR 需求【推导】 */
        public import ISQ::*;
        public import SI::*;
        private import ScalarValues::*;
        private import Requirements::*;

        part def '发动机';

        package '推进' {
            doc /* 推进功能域：推力与燃油经济性需求【推导】 */
            requirement <'IR-01'> 'ThrustCapability' : RequirementCheck {
                doc /* 净推力预测值不低于要求值【推导】 */
                subject '发动机' : '发动机';
                attribute '目标值' : Real;
                attribute '预测值' : Real;
                require constraint { '预测值' >= '目标值' }
            }
            requirement <'IR-02'> 'FuelEconomy' : RequirementCheck {
                doc /* 耗油率预测值不高于允许上限【推导】 */
                subject '发动机' : '发动机';
                attribute '目标值' : Real;
                attribute '预测值' : Real;
                require constraint { '预测值' <= '目标值' }
            }
        }

        package '调节' {
            doc /* 调节功能域：可用裕度需求【推导】 */
            requirement <'IR-04'> 'Operability' : RequirementCheck {
                doc /* 最小喘振裕度预测值不低于要求裕度【推导】 */
                subject '发动机' : '发动机';
                attribute '目标值' : Real;
                attribute '预测值' : Real;
                require constraint { '预测值' >= '目标值' }
            }
        }

        package '起停' {
            doc /* 起停功能域：起动时间需求【推导】 */
            requirement <'IR-03'> 'StartTime' : RequirementCheck {
                doc /* 起动时间预测值不高于允许值【推导】 */
                subject '发动机' : '发动机';
                attribute '目标值' :> ISQ::duration;
                attribute '预测值' :> ISQ::duration;
                require constraint { '预测值' <= '目标值' }
            }
        }

        package '保护' {
            doc /* 保护功能域：保护响应延迟需求【推导】 */
            requirement <'IR-05'> 'ProtectionLatency' : RequirementCheck {
                doc /* 保护检测与作动时间不高于允许响应时间【推导】 */
                subject '发动机' : '发动机';
                attribute '目标值' :> ISQ::duration;
                attribute '预测值' :> ISQ::duration;
                require constraint { '预测值' <= '目标值' }
            }
        }
    }

