    package '用例' {
        doc /* 航空涡扇发动机用例视图 - 发动机级 UC */
        private import UseCases::UseCase;
        private import Parts::Part;
        private import '需求'::*;

        part def '发动机';

        package '发动机用例' {
            use case def '推力指令' {
                doc /* 接收飞机推力需求并传递给 FADEC【推导】 */
                subject '发动机系统' : '发动机';
                actor '飞机' : Part;
                actor '驾驶员' : Part;
                objective {
                    doc /* 响应推力指令并执行控制 */
                    require '需求'::'推进'::'ThrustCapability';
                    require '需求'::'推进'::'FuelEconomy';
                }
            }
            use case def '起动与停车' {
                doc /* 接收飞机电力供应以控制发动机起动与停车【推导】 */
                subject '发动机系统' : '发动机';
                actor '飞机' : Part;
                actor '地面维护' : Part;
                objective {
                    doc /* 完成发动机起动与停车流程 */
                    require '需求'::'起停'::'StartTime';
                }
            }
            use case def '引气与功率提取' {
                doc /* 向飞机提供引气与电力供应【推导】 */
                subject '发动机系统' : '发动机';
                actor '飞机' : Part;
                objective {
                    doc /* 管理引气与功率提取 */
                    require '需求'::'调节'::'Operability';
                }
            }
            use case def '状态通报' {
                doc /* 向飞机通报控制状态与健康状态【推导】 */
                subject '发动机系统' : '发动机';
                actor '飞机' : Part;
                actor '地面维护' : Part;
                objective {
                    doc /* 提供发动机状态信息 */
                    require '需求'::'保护'::'ProtectionLatency';
                }
            }
        }
    }

    package '活动' {
        doc /* 航空涡扇发动机级活动图 */
        private import Actions::Action;
