        package 'propulsion' {
            action 'captureAir' : Action { out 'airflow' : Item; }
            action 'compressFan' : Action { in 'airflow' : Item; out 'fanCompressedAir' : Item; }
            action 'compressCore' : Action { in 'fanCompressedAir' : Item; out 'coreCompressedAir' : Item; }
            action 'injectFuel' : Action { in 'coreCompressedAir' : Item; in 'meteredFuel' : Item; out 'fuelAirMixture' : Item; }
            action 'igniteMixture' : Action { in 'fuelAirMixture' : Item; out 'ignitedMixture' : Item; }
