            part 'sensors' : 'Sensors' { port 'sensorOut' : 'SensorPort'; port 'serviceIn' : 'ServicePort'; }
            part 'healthMonitor' : 'HealthMonitor' { port 'healthIn' : 'HealthPort'; port 'sensorIn' : 'SensorPort'; port 'statusOut' : 'StatusPort'; }

            bind 'ambient' = 'inlet'.'gasIn';
            bind 'aircraftFuel' = 'fuel'.'fuelIn';
            bind 'aircraftElectric' = 'fadec'.'electricIn';
            bind 'demand' = 'fadec'.'demandIn';
