            connection 'I23' connect 'starter'.'shaftOut' to ~'gearbox'.'shaftIn';
            connection 'I18' connect 'oil'.'oilOut' to ~'hpSpool'.'shaftIn';
            connection 'I19' connect 'oil'.'oilOut' to ~'lpSpool'.'shaftIn';
            connection 'I20' connect 'oil'.'oilOut' to ~'gearbox'.'shaftIn';
            connection 'I21' connect 'oil'.'oilReturn' to ~'thermal'.'heatIn';
            connection 'I22' connect 'combustor'.'heatOut' to ~'oil'.'heatIn';
