            connection 'I26' connect 'sensors'.'sensorOut' to ~'healthMonitor'.'sensorIn';
            connection 'I27' connect 'fadec'.'fuelCommandOut' to ~'fuel'.'commandIn';
            connection 'I28' connect 'fadec'.'geometryCommandOut' to ~'coreNozzle'.'gasIn';
            connection 'I29' connect 'fadec'.'startCommandOut' to ~'starter'.'startCommandIn';
