    package '时序' {
        doc /* 航空涡扇发动机运行场景时序本体 */
        private import ScalarValues::*;
        private import Parts::Part;

        item def 'StartRequested 消息';
        item def 'LightOffConfirmed 消息';
        item def 'IdleReached 消息';
        item def 'AccelerationRequested 消息';
        item def 'TargetReached 消息';
        item def 'DecelerationRequested 消息';
        item def 'StopRequested 消息';
        item def 'EmergencyStopRequested 消息';
        item def 'DegradationDetected 消息';
        item def 'RecoveryConfirmed 消息';
        item def 'RelightRequested 消息';
        item def 'RotorStopped 消息';
        item def 'StartAborted 消息';
        item def 'StartTimedOut 消息';

        occurrence def '正常起动序列' {
            doc /* 场景路径 1：off→cranking→lighting→running */
            part '飞机'[1] : Part { event occurrence 'StartRequested 发送'; }
            part 'FADEC'[1] : Part { event occurrence 'StartRequested 接收'; then event occurrence 'LightOffConfirmed 发送'; then event occurrence 'IdleReached 发送'; then event occurrence 'AccelerationRequested 发送'; then event occurrence 'TargetReached 发送'; }
            part '起动机'[1] : Part { event occurrence 'StartRequested 接收'; then event occurrence 'LightOffConfirmed 接收'; }
            part '点火系统'[1] : Part { event occurrence 'LightOffConfirmed 接收'; }
            part '燃油计量单元'[1] : Part { event occurrence 'IdleReached 接收'; then event occurrence 'AccelerationRequested 接收'; then event occurrence 'TargetReached 接收'; }

            message 'StartRequested' of 'StartRequested 消息'[1] from '飞机'.'StartRequested 发送' to 'FADEC'.'StartRequested 接收';
            message 'StartRequested 转发' of 'StartRequested 消息'[1] from 'FADEC'.'StartRequested 接收' to '起动机'.'StartRequested 接收';
            message 'LightOffConfirmed' of 'LightOffConfirmed 消息'[1] from '起动机'.'LightOffConfirmed 接收' to 'FADEC'.'LightOffConfirmed 发送';
            message 'LightOffConfirmed 触发' of 'LightOffConfirmed 消息'[1] from 'FADEC'.'LightOffConfirmed 发送' to '点火系统'.'LightOffConfirmed 接收';
            message 'IdleReached' of 'IdleReached 消息'[1] from '燃油计量单元'.'IdleReached 接收' to 'FADEC'.'IdleReached 发送';
            message 'AccelerationRequested' of 'AccelerationRequested 消息'[1] from 'FADEC'.'AccelerationRequested 发送' to '燃油计量单元'.'AccelerationRequested 接收';
            message 'TargetReached' of 'TargetReached 消息'[1] from '燃油计量单元'.'TargetReached 接收' to 'FADEC'.'TargetReached 发送';
        }

        occurrence def '减速序列' {
            doc /* 场景路径 2：steady→decelerating→idle */
            part 'FADEC'[1] : Part { event occurrence 'DecelerationRequested 发送'; then event occurrence 'IdleReached 接收'; }
            part '燃油计量单元'[1] : Part { event occurrence 'DecelerationRequested 接收'; then event occurrence 'IdleReached 发送'; }
            part '压气机'[1] : Part { event occurrence 'DecelerationRequested 接收'; }
            part '涡轮'[1] : Part { event occurrence 'DecelerationRequested 接收'; }

