        part def '发动机' {
            exhibit state '发动机级状态机' {
                entry action initial;
                transition initial then 'off';

                state 'off' { do 'inhibitFuel'; }
                state 'cranking' { do 'driveStarter'; }
                state 'lighting' { do 'establishFlame'; }

                state 'running' {
                    entry action initial;
                    transition initial then 'idle';
                    state 'idle' {}
                    state 'accelerating' {}
                    state 'steady' {}
                    state 'decelerating' {}

                    transition 'idle 到 accelerating' first 'idle' accept 'AccelerationRequested' : 'AccelerationRequested' then 'accelerating';
                    transition 'accelerating 到 steady' first 'accelerating' accept 'TargetReached' : 'TargetReached' then 'steady';
                    transition 'steady 到 decelerating' first 'steady' accept 'DecelerationRequested' : 'DecelerationRequested' then 'decelerating';
                    transition 'decelerating 到 idle' first 'decelerating' accept 'IdleReached' : 'IdleReached' if 'idleStable' then 'idle';
                }

                state 'degraded' { do 'limitAvailableThrust'; }
                state 'relighting' { do 'attemptRelight'; }
                state 'shuttingDown' { do 'isolateFuelAndCoast'; }

                transition 'off 到 cranking' first 'off' accept 'StartRequested' : 'StartRequested' if 'startPermitted' then 'cranking';
