                transition 'relighting 到 running' first 'relighting' accept 'RelightRequested' : 'RelightRequested' if 'relightPermitted' then 'running';

                transition 'off 到 shuttingDown_正常' first 'off' accept 'StopRequested' : 'StopRequested' then 'shuttingDown';
                transition 'cranking 到 shuttingDown_正常' first 'cranking' accept 'StopRequested' : 'StopRequested' then 'shuttingDown';
                transition 'lighting 到 shuttingDown_正常' first 'lighting' accept 'StopRequested' : 'StopRequested' then 'shuttingDown';
                transition 'running 到 shuttingDown_正常' first 'running' accept 'StopRequested' : 'StopRequested' then 'shuttingDown';
