                transition 'relighting 到 shuttingDown_紧急' first 'relighting' accept 'EmergencyStopRequested' : 'EmergencyStopRequested' then 'shuttingDown';

                transition 'off 到 shuttingDown_中止' first 'off' accept 'StartAborted' : 'StartAborted' then 'shuttingDown';
