                doc /* 燃油端口：接收燃油系统供给的燃油。【推导】 */
                port 'gasOutlet' : 'GasPort';
                doc /* 气体端口：输出高温高压燃气至高压涡轮。【推导】 */
            }
            part def 'HPT' {
                doc /* 高压涡轮：从高温高压燃气中提取能量，驱动高压压气机。【推导】 */
                port 'gasInlet' : 'GasPort';
                doc /* 气体端口：接收燃烧室输出的高温高压燃气。【推导】 */
                port 'gasOutlet' : 'GasPort';
                doc /* 气体端口：输出膨胀后的燃气至低压涡轮。【推导】 */
                port 'power' : 'ShaftPort';
                doc /* 轴端口：输出机械功率至高压转子。【推导】 */
            }
            part def 'LPT' {
                doc /* 低压涡轮：从燃气中继续提取能量，驱动风扇与低压压气机。【推导】 */
                port 'gasInlet' : 'GasPort';
                doc /* 气体端口：接收高压涡轮输出的燃气。【推导】 */
                port 'gasOutlet' : 'GasPort';
                doc /* 气体端口：输出膨胀后的燃气至核心喷管。【推导】 */
                port 'power' : 'ShaftPort';
                doc /* 轴端口：输出机械功率至低压转子。【推导】 */
            }
            part def 'Nozzle' {
                doc /* 喷管：将燃气加速排出，产生推力。本类型被实例化为 coreNozzle 与 bypassNozzle 两个实例。【推导】 */
                port 'inlet' : 'GasPort';
                doc /* 气体端口：接收待加速的气流。【推导】 */
                port 'force' : 'ThrustPort';
                doc /* 推力端口：输出推力至安装节。【推导】 */
            }
            part def 'Mount' {
                doc /* 安装节：将发动机推力传递至飞机结构，承受力学载荷。【推导】 */
                port 'coreForce' : 'ThrustPort';
                doc /* 推力端口：接收核心喷管产生的推力。【推导】 */
                port 'bypassForce' : 'ThrustPort';
                doc /* 推力端口：接收外涵喷管产生的推力。【推导】 */
                port 'netForce' : 'MountPort';
                doc /* 安装端口：向飞机输出净推力。【推导】 */
            }
            part def 'HPSpool' {
                doc /* 高压转子：连接高压涡轮与高压压气机，传递轴功率。【推导】 */
                port 'turbine' : 'ShaftPort';
                doc /* 轴端口：接收高压涡轮输出的机械功率。【推导】 */
                port 'compressor' : 'ShaftPort';
                doc /* 轴端口：向高压压气机传递机械功率。【推导】 */
            }
            part def 'LPSpool' {
                doc /* 低压转子：连接低压涡轮与风扇，传递轴功率。【推导】 */
                port 'turbine' : 'ShaftPort';
                doc /* 轴端口：接收低压涡轮输出的机械功率。【推导】 */
                port 'fan' : 'ShaftPort';
                doc /* 轴端口：向风扇传递机械功率。【推导】 */
            }

            /* --- 调节域部件定义 --- */
            part def 'FADEC' {
                doc /* 全权限数字电子控制器：负责发动机全权限控制，包含双通道冗余架构。【推导】 */
                port 'demand' : 'CommandPort';
                doc /* 指令端口：接收飞机发送的推力需求指令。【推导】 */
                port 'feedback' : 'FeedbackPort';
                doc /* 反馈端口：接收传感器反馈的测量信号。【推导】 */
                port 'status' : 'StatusPort';
                doc /* 状态端口：向飞机输出控制状态信息。【推导】 */
                part 'channelA' : 'ControlChannel';
                doc /* A 通道：主控制通道。【推导】 */
                part 'channelB' : 'ControlChannel';
                doc /* B 通道：冗余控制通道。【推导】 */
            }
            part def 'ControlChannel' {
                doc /* 控制通道：FADEC 内的独立控制计算单元，支持双通道冗余。【推导】 */
            }

            /* --- 起停域部件定义 --- */
            part def 'Starter' {
                doc /* 起动机：在起动阶段为转子提供初始驱动力。【推导】 */
                port 'supply' : 'ElectricPort';
                doc /* 电端口：接收飞机提供的起动电能。【推导】 */
                port 'drive' : 'ShaftPort';
                doc /* 轴端口：向转子输出起动机械功率。【推导】 */
            }

            /* --- 服务域部件定义 --- */
            part def 'Fuel' {
                doc /* 燃油系统：负责燃油的存储、计量与供给。【推导】 */
                port 'supply' : 'FuelPort';
                doc /* 燃油端口：接收飞机供给的燃油。【推导】 */
                port 'metered' : 'FuelPort';
                doc /* 燃油端口：向燃烧室输出计量后的燃油。【推导】 */
                port 'command' : 'CommandPort';
                doc /* 指令端口：接收 FADEC 的燃油计量指令。【推导】 */
            }
            part def 'Oil' {
                doc /* 滑油系统：负责轴承与齿轮的润滑与冷却。【推导】 */
                port 'distribution' : 'OilPort';
                doc /* 滑油端口：向轴承与齿轮分配滑油。【推导】 */
            }
            part def 'Thermal' {
                doc /* 热管理系统：负责发动机散热与热管理。【推导】 */
                port 'rejectedHeat' : 'HeatPort';
                doc /* 热端口：向环境散发废热。【推导】 */
            }
            part def 'Bleed' {
                doc /* 引气系统：负责从压气机提取引气供飞机使用。【推导】 */
                port 'aircraftBleed' : 'GasPort';
                doc /* 气体端口：向飞机输出引气。【推导】 */
            }
            part def 'Gearbox' {
                doc /* 附件齿轮箱：从转子提取机械功率驱动附件。【推导】 */
                port 'input' : 'ShaftPort';
                doc /* 轴端口：接收转子输入的机械功率。【推导】 */
                port 'output' : 'ServicePort';
                doc /* 服务端口：向附件输出机械功率。【推导】 */
            }
            part def 'Generator' {
                doc /* 发电机：将机械功率转换为电功率供飞机使用。【推导】 */
                port 'input' : 'ShaftPort';
                doc /* 轴端口：接收齿轮箱输入的机械功率。【推导】 */
                port 'power' : 'ElectricPort';
                doc /* 电端口：向飞机输出电功率。【推导】 */
            }

            /* --- 保护域部件定义 --- */
            /* 保护域由 FADEC 承担，已在调节域定义 */

            /* --- 健康监测域部件定义 --- */
            part def 'Sensors' {
                doc /* 传感器组：采集发动机各部位的物理量测量信号。【推导】 */
                port 'measurements' : 'FeedbackPort';
                doc /* 反馈端口：向 FADEC 输出测量信号。【推导】 */
            }
            part def 'HealthMonitor' {
                doc /* 健康监测模块：评估发动机健康状态并输出诊断信息。【推导】 */
                port 'status' : 'StatusPort';
                doc /* 状态端口：向飞机输出健康状态信息。【推导】 */
            }

            /* --- 根部件定义 --- */
            part def 'Turbofan' {
                doc /* 双转子涡扇发动机根部件：按 6 大功能域树形组织 21 个部件实例。【推导】 */
                doc /* 产品背景：双转子、分排、无加力涡扇发动机。【推导】 */

                /* ===== 推进域 ===== */
                part inlet : 'Inlet';
                doc /* 进气道实例：捕获外部空气。【推导】 */
                part fan : 'Fan';
                doc /* 风扇实例：增压并分流内外涵气流。【推导】 */
                part hpc : 'HPC';
                doc /* 高压压气机实例：高压压缩内涵气流。【推导】 */
                part combustor : 'Combustor';
                doc /* 燃烧室实例：燃油燃烧产生高温高压燃气。【推导】 */
                part hpt : 'HPT';
                doc /* 高压涡轮实例：驱动高压压气机。【推导】 */
                part lpt : 'LPT';
                doc /* 低压涡轮实例：驱动风扇。【推导】 */
                part coreNozzle : 'Nozzle';
                doc /* 核心喷管实例：加速内涵燃气产生推力。【推导】 */
                part bypassNozzle : 'Nozzle';
                doc /* 外涵喷管实例：加速外涵气流产生推力。【推导】 */
                part mount : 'Mount';
                doc /* 安装节实例：传递推力至飞机。【推导】 */
                part hpSpool : 'HPSpool';
                doc /* 高压转子实例：连接 HPT 与 HPC。【推导】 */
                part lpSpool : 'LPSpool';
                doc /* 低压转子实例：连接 LPT 与 Fan。【推导】 */

                /* ===== 调节域 ===== */
                part fadec : 'FADEC';
                doc /* FADEC 实例：全权限数字电子控制器，含双通道冗余。【推导】 */

                /* ===== 起停域 ===== */
                part starter : 'Starter';
                doc /* 起动机实例：起动阶段提供初始驱动力。【推导】 */

                /* ===== 服务域 ===== */
                part fuel : 'Fuel';
                doc /* 燃油系统实例：燃油存储、计量与供给。【推导】 */
                part oil : 'Oil';
                doc /* 滑油系统实例：轴承与齿轮润滑冷却。【推导】 */
                part thermal : 'Thermal';
                doc /* 热管理系统实例：发动机散热。【推导】 */
                part bleed : 'Bleed';
                doc /* 引气系统实例：从压气机提取引气。【推导】 */
                part gearbox : 'Gearbox';
                doc /* 附件齿轮箱实例：提取机械功率驱动附件。【推导】 */
                part generator : 'Generator';
                doc /* 发电机实例：机械功率转换为电功率。【推导】 */

                /* ===== 保护域 ===== */
                /* 保护域由 FADEC 承担，已在调节域实例化 */

                /* ===== 健康监测域 ===== */
                part sensors : 'Sensors';
                doc /* 传感器组实例：采集物理量测量信号。【推导】 */
                part healthMonitor : 'HealthMonitor';
                doc /* 健康监测模块实例：评估发动机健康状态。【推导】 */
            }
        }

