        doc /* 产品背景：双转子、分排、无加力涡扇发动机；飞机只作为外部环境。【推导】 */
        doc /* 本图定义发动机与飞机的交互边界，含 3 类参与者、4 类用例、10 条边界委托分组；纯物理交换不转用例。【推导】 */
        doc /* 原模型 use case / actor 均为 0，本视图属新建。【推导】 */

        /* ===== 参与者定义 ===== */
        package '参与者定义' {
            doc /* 3 类参与者：飞机、驾驶员、地面维护。【推导】 */
            part def '飞机' {
                doc /* 飞机：作为外部环境，提供推力指令、起动电能、引气请求等，接收发动机状态通报。【推导】 */
            }
            part def '驾驶员' {
                doc /* 驾驶员：通过飞机系统间接与发动机交互，发出推力指令与起停请求。【推导】 */
            }
            part def '地面维护' {
                doc /* 地面维护：在地面维护阶段与发动机交互，接收健康状态通报。【推导】 */
            }
        }

        /* ===== 边界委托分组 ===== */
        package '边界委托分组' {
            doc /* 10 条边界委托，按派生维度分为 4 组（转用例）+ 1 组（纯物理交换，不转用例）。【推导】 */

            package '推力指令组' {
                doc /* 推力指令组：飞机向 FADEC 发送推力需求。【推导】 */
                doc /* 边界委托：demand → fadec.demand。【推导】 */
            }
            package '起动与停车组' {
                doc /* 起动与停车组：飞机向起动机提供起动电能。【推导】 */
                doc /* 边界委托：aircraftElectric → starter.supply。【推导】 */
            }
            package '引气与功率提取组' {
                doc /* 引气与功率提取组：发动机向飞机提供引气与电功率。【推导】 */
                doc /* 边界委托 1：bleedSupply → bleed.aircraftBleed。【推导】 */
                doc /* 边界委托 2：electricSupply → generator.power。【推导】 */
            }
            package '状态通报组' {
                doc /* 状态通报组：发动机向飞机通报控制状态与健康状态。【推导】 */
                doc /* 边界委托 1：controlStatus → fadec.status。【推导】 */
                doc /* 边界委托 2：healthStatus → healthMonitor.status。【推导】 */
            }
            package '纯物理交换（不转用例）' {
                doc /* 纯物理交换：不转化为用例，仅作为物理边界交换。【推导】 */
                doc /* 1. ambient → inlet.ambient：大气环境向进气道提供进气。【推导】 */
                doc /* 2. aircraftFuel → fuel.supply：飞机向燃油系统供给燃油。【推导】 */
                doc /* 3. thrust → mount.netForce：安装节向飞机输出净推力。【推导】 */
                doc /* 4. rejectedHeat → thermal.rejectedHeat：热管理系统向环境散发废热。【推导】 */
            }
        }

        /* ===== 4 类用例定义 ===== */
        use case def '推力指令' {
