            doc /* 依据边界委托：bleedSupply → bleed.aircraftBleed、electricSupply → generator.power。【推导】 */
            subject engine : '部件定义'::'Turbofan';
            doc /* 主体：整机。【推导】 */
            actor aircraft : '飞机';
            doc /* 参与者：飞机。【推导】 */
        }
        use case def '状态通报' {
            doc /* 状态通报用例：发动机向飞机通报控制状态与健康状态。【推导】 */
            doc /* 依据边界委托：controlStatus → fadec.status、healthStatus → healthMonitor.status。【推导】 */
            subject engine : '部件定义'::'Turbofan';
            doc /* 主体：整机。【推导】 */
            actor aircraft : '飞机';
            doc /* 参与者：飞机。【推导】 */
            actor maintenance : '地面维护';
            doc /* 参与者：地面维护。【推导】 */
        }

