            expose 'P3 用例图'::'边界委托分组'::'起动与停车组';
            expose 'P3 用例图'::'边界委托分组'::'引气与功率提取组';
            expose 'P3 用例图'::'边界委托分组'::'状态通报组';
            expose 'P3 用例图'::'边界委托分组'::'纯物理交换（不转用例）';
        }
