    package 'P4 活动图' {
        doc /* 发动机级活动图 —— 双转子涡扇发动机方案阶段功能架构概念基线 */
        doc /* 产品背景：双转子、分排、无加力涡扇发动机；飞机只作为外部环境。【推导】 */
        doc /* 本图定义 6 大功能域共 34 个叶功能、13 条 flow 输入输出依赖、5 类异常分支。【推导】 */
        doc /* 原模型 decide / fork / join / merge 均为 0；F2-F6 功能域无 flow。【推导】 */

        /* ===== 推进域（propulsion）===== */
        package 'propulsion' {
            doc /* 推进域：负责空气捕获、压缩、燃烧、膨胀、排气，产生推力。含推进链 11 条 flow。【推导】 */

            action def 'captureAir' {
                doc /* 捕获空气：进气道捕获外部大气并进行初步调节。【推导】 */
            }
            action def 'compressFan' {
                doc /* 风扇压缩：风扇对进气增压，分流为内涵与外涵气流。【推导】 */
            }
            action def 'compressHPC' {
                doc /* 高压压缩：高压压气机对内涵气流进行高压压缩。【推导】 */
            }
            action def 'burnFuel' {
                doc /* 燃烧：燃烧室将燃油与高压空气混合燃烧，产生高温高压燃气。【推导】 */
            }
            action def 'expandHPT' {
                doc /* 高压膨胀：高压涡轮从高温高压燃气中提取能量。【推导】 */
            }
            action def 'expandLPT' {
                doc /* 低压膨胀：低压涡轮从燃气中继续提取能量。【推导】 */
            }
            action def 'expandCoreJet' {
                doc /* 核心排气：核心喷管将内涵燃气加速排出产生推力。【推导】 */
            }
            action def 'expandBypassJet' {
                doc /* 外涵排气：外涵喷管将外涵气流加速排出产生推力。【推导】 */
            }
            action def 'driveHPSpool' {
                doc /* 高压转子驱动：高压涡轮通过高压转子驱动高压压气机。【推导】 */
            }
            action def 'driveLPSpool' {
                doc /* 低压转子驱动：低压涡轮通过低压转子驱动风扇。【推导】 */
            }
            action def 'generateThrust' {
                doc /* 产生推力：核心喷管与外涵喷管共同产生发动机总推力。【推导】 */
            }

            /* 推进链 flow（11 条） */
            action '推进链' {
                doc /* 推进链活动流：captureAir → compressFan → compressHPC → burnFuel → expandHPT → expandLPT → expandCoreJet，同时 expandBypassJet 与 compressFan 并行。【推导】 */

                action a1 : 'captureAir';
                doc /* 捕获空气。【推导】 */
                action a2 : 'compressFan';
                doc /* 风扇压缩。【推导】 */
                action a3 : 'compressHPC';
                doc /* 高压压缩。【推导】 */
                action a4 : 'burnFuel';
                doc /* 燃烧。【推导】 */
                action a5 : 'expandHPT';
                doc /* 高压膨胀。【推导】 */
                action a6 : 'expandLPT';
                doc /* 低压膨胀。【推导】 */
                action a7 : 'expandCoreJet';
                doc /* 核心排气。【推导】 */
                action a8 : 'expandBypassJet';
                doc /* 外涵排气。【推导】 */
                action a9 : 'driveHPSpool';
                doc /* 高压转子驱动。【推导】 */
                action a10 : 'driveLPSpool';
                doc /* 低压转子驱动。【推导】 */
                action a11 : 'generateThrust';
                doc /* 产生推力。【推导】 */

                succession flow 'f1' from a1 to a2;
                doc /* flow：captureAir → compressFan，进气道输出至风扇。【推导】 */
                succession flow 'f2' from a2 to a3;
                doc /* flow：compressFan → compressHPC，风扇内涵输出至高压压气机。【推导】 */
                succession flow 'f3' from a3 to a4;
                doc /* flow：compressHPC → burnFuel，高压空气进入燃烧室。【推导】 */
                succession flow 'f4' from a4 to a5;
                doc /* flow：burnFuel → expandHPT，高温燃气进入高压涡轮。【推导】 */
                succession flow 'f5' from a5 to a6;
                doc /* flow：expandHPT → expandLPT，燃气从高压涡轮进入低压涡轮。【推导】 */
                succession flow 'f6' from a6 to a7;
                doc /* flow：expandLPT → expandCoreJet，燃气从低压涡轮进入核心喷管。【推导】 */
                succession flow 'f7' from a2 to a8;
                doc /* flow：compressFan → expandBypassJet，风扇外涵气流进入外涵喷管。【推导】 */
                succession flow 'f8' from a5 to a9;
                doc /* flow：expandHPT → driveHPSpool，高压涡轮功率传递至高压转子。【推导】 */
                succession flow 'f9' from a9 to a3;
                doc /* flow：driveHPSpool → compressHPC，高压转子驱动高压压气机。【推导】 */
                succession flow 'f10' from a6 to a10;
                doc /* flow：expandLPT → driveLPSpool，低压涡轮功率传递至低压转子。【推导】 */
                succession flow 'f11' from a10 to a2;
                doc /* flow：driveLPSpool → compressFan，低压转子驱动风扇。【推导】 */
            }
        }

        /* ===== 调节域（regulation）===== */
        package 'regulation' {
            doc /* 调节域：负责推力调节与燃油计量控制。F2 无 flow。【推导】 */

            action def 'regulateThrust' {
