            }
            action def 'controlGeometry' {
                doc /* 几何控制：FADEC 控制可调几何部件的开度。【推导】 */
            }
            action def 'scheduleSchedule' {
                doc /* 调度管理：FADEC 根据飞行工况调度各控制回路。【推导】 */
            }
            action def 'monitorLimits' {
                doc /* 限制监控：FADEC 监控各参数是否超出安全限制。【推导】 */
            }
            action def 'computeControl' {
                doc /* 控制计算：FADEC 执行控制律计算。【推导】 */
            }
        }

        /* ===== 起停域（startStop）===== */
        package 'startStop' {
            doc /* 起停域：负责发动机起动与停车序列控制。F3 无 flow。【推导】 */

            action def 'initiateStart' {
                doc /* 起动初始化：接收起动指令，初始化起动序列。【推导】 */
            }
            action def 'driveStarter' {
                doc /* 起动机驱动：起动机为转子提供初始驱动力。【推导】 */
            }
            action def 'establishFlame' {
                doc /* 建立火焰：点火并建立稳定燃烧。【推导】 */
            }
            action def 'accelerateToIdle' {
                doc /* 加速至慢车：转子加速至慢车转速。【推导】 */
            }
            action def 'stabilizeIdle' {
                doc /* 慢车稳定：在慢车状态稳定运行。【推导】 */
            }
            action def 'sequenceStop' {
                doc /* 停车序列：执行正常停车序列。【推导】 */
            }
        }

        /* ===== 服务域（services）===== */
        package 'services' {
            doc /* 服务域：负责燃油供应、滑油管理、热管理、引气、附件功率提取。F4 无 flow。【推导】 */

            action def 'supplyFuel' {
                doc /* 燃油供给：燃油系统存储并供给燃油。【推导】 */
            }
            action def 'meteredFuel' {
