    package 'P5 内部块图' {
        private import 'P2 结构图'::*;
        doc /* 发动机级内部块图 IBD —— 双转子涡扇发动机方案阶段功能架构概念基线 */
        doc /* 产品背景：双转子、分排、无加力涡扇发动机；飞机只作为外部环境。【推导】 */
        doc /* 本图定义 31 条内部接口（按 11 类交换类型分组）、10 条边界委托外部端口。【推导】 */
        doc /* 端口方向规则：源端 out，接收端一律共轭 ~。【推导】 */

        /* ===== 10 条边界委托外部端口 ===== */
        package '边界端口' {
            doc /* 10 个外部端口：定义发动机与飞机/环境的边界委托。【推导】 */
            port ambient : '端口定义'::'AmbientPort';
            doc /* 环境端口：接收外部大气至进气道。边界委托：ambient → inlet.ambient。【推导】 */
            port aircraftFuel : '端口定义'::'FuelPort';
            doc /* 飞机燃油端口：接收飞机供给的燃油。边界委托：aircraftFuel → fuel.supply。【推导】 */
            port aircraftElectric : '端口定义'::'ElectricPort';
            doc /* 飞机电端口：接收飞机提供的起动电能。边界委托：aircraftElectric → starter.supply。【推导】 */
            port demand : '端口定义'::'CommandPort';
            doc /* 需求指令端口：接收飞机发送的推力需求。边界委托：demand → fadec.demand。【推导】 */
            port thrust : '端口定义'::'MountPort';
            doc /* 推力输出端口：向飞机输出净推力。边界委托：thrust → mount.netForce。【推导】 */
            port controlStatus : '端口定义'::'StatusPort';
            doc /* 控制状态端口：向飞机通报控制状态。边界委托：controlStatus → fadec.status。【推导】 */
            port healthStatus : '端口定义'::'StatusPort';
            doc /* 健康状态端口：向飞机通报健康状态。边界委托：healthStatus → healthMonitor.status。【推导】 */
            port bleedSupply : '端口定义'::'GasPort';
            doc /* 引气供给端口：向飞机输出引气。边界委托：bleedSupply → bleed.aircraftBleed。【推导】 */
            port electricSupply : '端口定义'::'ElectricPort';
            doc /* 电功率供给端口：向飞机输出电功率。边界委托：electricSupply → generator.power。【推导】 */
            port rejectedHeat : '端口定义'::'HeatPort';
            doc /* 废热散发端口：向环境散发废热。边界委托：rejectedHeat → thermal.rejectedHeat。【推导】 */
        }

        /* ===== 31 条内部接口（按 11 类交换类型分组）===== */
        package '内部接口' {

            /* --- Gas 类（9 条）--- */
            package 'Gas 类接口' {
                doc /* Gas 类接口：气体载荷在部件间的流动交换，共 9 条。【推导】 */
                connection 'I01' from inlet.conditioned to fan.inlet;
                doc /* I01 Gas：进气道调节后的空气输出至风扇入口。【推导】 */
                connection 'I02' from fan.core to hpc.inlet;
                doc /* I02 Gas：风扇内涵气流输出至高压压气机入口。【推导】 */
                connection 'I03' from hpc.outlet to combustor.airInlet;
                doc /* I03 Gas：高压压气机输出高压空气至燃烧室。【推导】 */
                connection 'I04' from combustor.gasOutlet to hpt.gasInlet;
                doc /* I04 Gas：燃烧室输出高温高压燃气至高压涡轮。【推导】 */
                connection 'I05' from hpt.gasOutlet to lpt.gasInlet;
                doc /* I05 Gas：高压涡轮输出膨胀后燃气至低压涡轮。【推导】 */
                connection 'I06' from lpt.gasOutlet to coreNozzle.inlet;
                doc /* I06 Gas：低压涡轮输出燃气至核心喷管。【推导】 */
                connection 'I07' from fan.bypass to bypassNozzle.inlet;
                doc /* I07 Gas：风扇外涵气流输出至外涵喷管。【推导】 */
                connection 'I08' from bleed.aircraftBleed to bleedSupply;
                doc /* I08 Gas：引气系统向飞机输出引气（边界委托）。【推导】 */
                connection 'I09' from ambient to inlet.ambient;
                doc /* I09 Gas：外部大气进入进气道（边界委托）。【推导】 */
            }

            /* --- Fuel 类（1 条）--- */
            package 'Fuel 类接口' {
                doc /* Fuel 类接口：燃油载荷的交换，共 1 条。【推导】 */
                connection 'I10' from fuel.metered to combustor.fuelInlet;
                doc /* I10 Fuel：燃油系统计量后的燃油供给燃烧室。【推导】 */
            }

            /* --- ShaftPower 类（8 条）--- */
            package 'ShaftPower 类接口' {
                doc /* ShaftPower 类接口：轴功率在转子与部件间的传递，共 8 条。【推导】 */
                connection 'I11' from hpt.power to hpSpool.turbine;
                doc /* I11 ShaftPower：高压涡轮输出功率至高压转子。【推导】 */
                connection 'I12' from hpSpool.compressor to hpc.shaft;
                doc /* I12 ShaftPower：高压转子驱动高压压气机。【推导】 */
                connection 'I13' from lpt.power to lpSpool.turbine;
                doc /* I13 ShaftPower：低压涡轮输出功率至低压转子。【推导】 */
                connection 'I14' from lpSpool.fan to fan.shaft;
                doc /* I14 ShaftPower：低压转子驱动风扇。【推导】 */
                connection 'I15' from starter.drive to lpSpool.fan;
                doc /* I15 ShaftPower：起动机驱动低压转子（起动阶段）。【推导】 */
                connection 'I16' from gearbox.input to lpSpool.fan;
                doc /* I16 ShaftPower：低压转子向附件齿轮箱输入功率。【推导】 */
                connection 'I17' from gearbox.output to generator.input;
                doc /* I17 ShaftPower：附件齿轮箱向发电机输入机械功率。【推导】 */
                connection 'I23' from hpSpool.turbine to hpt.power;
                doc /* I23 ShaftPower：高压转子与高压涡轮之间的功率传递（反向回路）。【推导】 */
            }

            /* --- Oil 类（4 条）--- */
            package 'Oil 类接口' {
                doc /* Oil 类接口：滑油在系统中的分配交换，共 4 条。【推导】 */
                connection 'I18' from oil.distribution to hpSpool.turbine;
                doc /* I18 Oil：滑油系统向高压转子轴承分配滑油。【推导】 */
                connection 'I19' from oil.distribution to lpSpool.turbine;
                doc /* I19 Oil：滑油系统向低压转子轴承分配滑油。【推导】 */
                connection 'I20' from oil.distribution to gearbox.input;
                doc /* I20 Oil：滑油系统向附件齿轮箱分配滑油。【推导】 */
                connection 'I21' from oil.distribution to starter.drive;
                doc /* I21 Oil：滑油系统向起动机分配滑油。【推导】 */
            }

            /* --- Heat 类（1 条）--- */
            package 'Heat 类接口' {
                doc /* Heat 类接口：热量载荷的交换，共 1 条。【推导】 */
                connection 'I22' from thermal.rejectedHeat to rejectedHeat;
                doc /* I22 Heat：热管理系统向环境散发废热（边界委托）。【推导】 */
            }

            /* --- ElectricPower 类（1 条）--- */
            package 'ElectricPower 类接口' {
                doc /* ElectricPower 类接口：电功率的交换，共 1 条。【推导】 */
                connection 'I24' from generator.power to electricSupply;
                doc /* I24 ElectricPower：发电机向飞机输出电功率（边界委托）。【推导】 */
            }

            /* --- Feedback 类（2 条）--- */
            package 'Feedback 类接口' {
                doc /* Feedback 类接口：传感器反馈信号的交换，共 2 条。【推导】 */
                doc /* 多域接口标注：I25 跨 propulsion → regulation 域。【推导】 */
                connection 'I25' from sensors.measurements to fadec.feedback;
                doc /* I25 Feedback：传感器组向 FADEC 反馈测量信号。跨域影响：propulsion → regulation。【推导】 */
                connection 'I26' from sensors.measurements to healthMonitor.status;
                doc /* I26 Feedback：传感器组向健康监测模块输出测量信号。【推导】 */
            }

            /* --- FuelCommand 类（1 条）--- */
            package 'FuelCommand 类接口' {
                doc /* FuelCommand 类接口：燃油控制指令的交换，共 1 条。【推导】 */
                doc /* 多域接口标注：I27 跨 regulation → services 域。【推导】 */
                connection 'I27' from fadec.demand to fuel.command;
                doc /* I27 FuelCommand：FADEC 向燃油系统发出计量指令。跨域影响：regulation → services。【推导】 */
            }

            /* --- GeometryCommand 类（1 条）--- */
            package 'GeometryCommand 类接口' {
                doc /* GeometryCommand 类接口：几何控制指令的交换，共 1 条。【推导】 */
                doc /* 多域接口标注：I28 跨 regulation → propulsion 域。【推导】 */
                connection 'I28' from fadec.demand to hpc.shaft;
                doc /* I28 GeometryCommand：FADEC 向高压压气机发出可调几何指令。跨域影响：regulation → propulsion。【推导】 */
            }

            /* --- StartCommand 类（1 条）--- */
            package 'StartCommand 类接口' {
                doc /* StartCommand 类接口：起动控制指令的交换，共 1 条。【推导】 */
                doc /* 多域接口标注：I29 跨 regulation → startStop 域。【推导】 */
                connection 'I29' from fadec.demand to starter.supply;
                doc /* I29 StartCommand：FADEC 向起动机发出起动/停车指令。跨域影响：regulation → startStop。【推导】 */
            }

            /* --- Thrust 类（2 条）--- */
            package 'Thrust 类接口' {
                doc /* Thrust 类接口：推力载荷的传递，共 2 条。【推导】 */
                doc /* 口径声明：净推力由外部循环与安装分析给出，不等于 I30 与 I31 之和。【推导】 */
                connection 'I30' from coreNozzle.force to mount.coreForce;
                doc /* I30 Thrust：核心喷管产生的推力传递至安装节。【推导】 */
                connection 'I31' from bypassNozzle.force to mount.bypassForce;
                doc /* I31 Thrust：外涵喷管产生的推力传递至安装节。【推导】 */
            }
        }

