    package 'P6 时序图' {
        private import 'P2 结构图'::*;
        private import 'P3 用例图'::*;
        doc /* 发动机级时序图 —— 双转子涡扇发动机方案阶段功能架构概念基线 */
        doc /* 产品背景：双转子、分排、无加力涡扇发动机；飞机只作为外部环境。【推导】 */
        doc /* 本图定义 14 个事件、6 个守卫、5 条场景路径的时序交互。【推导】 */
        doc /* 原模型 interaction / message / participant 均为 0，本视图属新建。【推导】 */

        /* ===== 14 个事件定义 ===== */
        package '事件定义' {
            doc /* 14 个事件：定义状态转换的触发事件。【推导】 */
            event def 'StartRequested' {
                doc /* 起动请求事件：驾驶员或飞机系统请求发动机起动。【推导】 */
            }
            event def 'LightOffConfirmed' {
                doc /* 点火确认事件：燃烧室点火成功确认。【推导】 */
            }
            event def 'IdleReached' {
                doc /* 慢车到达事件：转子转速达到慢车状态。【推导】 */
            }
            event def 'AccelerationRequested' {
                doc /* 加速请求事件：推力指令增加，请求加速。【推导】 */
            }
            event def 'TargetReached' {
                doc /* 目标到达事件：达到目标推力或转速。【推导】 */
            }
            event def 'DecelerationRequested' {
                doc /* 减速请求事件：推力指令减少，请求减速。【推导】 */
            }
            event def 'StopRequested' {
                doc /* 停车请求事件：正常停车请求。【推导】 */
            }
            event def 'EmergencyStopRequested' {
                doc /* 紧急停车请求事件：紧急停车请求。【推导】 */
            }
            event def 'DegradationDetected' {
                doc /* 降级检测事件：检测到可容忍故障，需降级运行。【推导】 */
            }
            event def 'RecoveryConfirmed' {
                doc /* 恢复确认事件：故障恢复确认。【推导】 */
            }
            event def 'RelightRequested' {
                doc /* 再起动请求事件：请求重新点火起动。【推导】 */
            }
            event def 'RotorStopped' {
                doc /* 转子停止事件：转子完全停止。【推导】 */
            }
            event def 'StartAborted' {
                doc /* 起动中止事件：起动过程中止。【推导】 */
            }
            event def 'StartTimedOut' {
                doc /* 起动超时事件：起动过程超时。【推导】 */
            }
        }

        /* ===== 6 个守卫定义 ===== */
        package '守卫定义' {
            doc /* 6 个守卫：定义状态转换的条件守卫（Boolean，不得默认置真）。【推导】 */
            attribute def 'startPermitted' {
                doc /* 起动允许守卫：判断起动条件是否满足。【推导】 */
            }
            attribute def 'lightOffValid' {
                doc /* 点火有效守卫：判断点火是否有效建立。【推导】 */
            }
            attribute def 'idleStable' {
                doc /* 慢车稳定守卫：判断慢车状态是否稳定。【推导】 */
            }
            attribute def 'recoverable' {
                doc /* 可恢复守卫：判断故障是否可恢复。【推导】 */
            }
            attribute def 'relightPermitted' {
                doc /* 再起动允许守卫：判断再起动条件是否满足。【推导】 */
            }
            attribute def 'coolDownComplete' {
                doc /* 冷却完成守卫：判断冷却过程是否完成。【推导】 */
            }
        }

        /* ===== 5 条场景路径 ===== */
        package '场景路径' {

            /* --- 场景 1：正常起动 --- */
            interaction def '正常起动' {
                doc /* 正常起动场景：off → cranking → lighting → running（含 idle / accelerating / steady / decelerating 子状态）。【推导】 */
                doc /* 消息由 14 个事件与转换路径派生，每条消息注明来源转换。【推导】 */

                part aircraft : '参与者定义'::'飞机';
                doc /* 生命线：飞机（外部环境）。【推导】 */
                part fadec : '部件定义'::'FADEC';
                doc /* 生命线：FADEC。【推导】 */
                part starter : '部件定义'::'Starter';
                doc /* 生命线：起动机。【推导】 */
                part combustor : '部件定义'::'Combustor';
                doc /* 生命线：燃烧室。【推导】 */

                message m1 from aircraft to fadec;
                doc /* 消息 m1：飞机向 FADEC 发送 StartRequested 事件。来源转换：off → cranking。【推导】 */
                message m2 from fadec to starter;
                doc /* 消息 m2：FADEC 向起动机发送起动指令（守卫：startPermitted）。来源转换：off → cranking。【推导】 */
                message m3 from starter to fadec;
                doc /* 消息 m3：起动机向 FADEC 反馈转子转动。来源转换：cranking → lighting。【推导】 */
                message m4 from fadec to combustor;
                doc /* 消息 m4：FADEC 向燃烧室发送点火指令。来源转换：cranking → lighting。【推导】 */
                message m5 from combustor to fadec;
                doc /* 消息 m5：燃烧室向 FADEC 反馈 LightOffConfirmed 事件（守卫：lightOffValid）。来源转换：lighting → running.idle。【推导】 */
                message m6 from fadec to fadec;
                doc /* 消息 m6：FADEC 内部确认 IdleReached 事件（守卫：idleStable）。来源转换：running.idle → running.accelerating。【推导】 */
                message m7 from fadec to fadec;
                doc /* 消息 m7：FADEC 内部确认 AccelerationRequested 事件。来源转换：running.accelerating → running.steady。【推导】 */
                message m8 from fadec to aircraft;
                doc /* 消息 m8：FADEC 向飞机反馈 TargetReached 事件。来源转换：running.accelerating → running.steady。【推导】 */
            }

            /* --- 场景 2：减速 --- */
            interaction def '减速' {
                doc /* 减速场景：steady → decelerating → idle。【推导】 */

                part aircraft : '参与者定义'::'飞机';
                doc /* 生命线：飞机。【推导】 */
                part fadec : '部件定义'::'FADEC';
                doc /* 生命线：FADEC。【推导】 */

                message m1 from aircraft to fadec;
                doc /* 消息 m1：飞机向 FADEC 发送 DecelerationRequested 事件。来源转换：running.steady → running.decelerating。【推导】 */
                message m2 from fadec to fadec;
                doc /* 消息 m2：FADEC 内部执行减速控制。来源转换：running.decelerating → running.idle。【推导】 */
                message m3 from fadec to aircraft;
                doc /* 消息 m3：FADEC 向飞机反馈减速完成。来源转换：running.decelerating → running.idle。【推导】 */
            }

            /* --- 场景 3：降级与再起动 --- */
            interaction def '降级与再起动' {
                doc /* 降级与再起动场景：running → degraded → relighting → running。【推导】 */

                part fadec : '部件定义'::'FADEC';
                doc /* 生命线：FADEC。【推导】 */
                part healthMonitor : '部件定义'::'HealthMonitor';
                doc /* 生命线：健康监测模块。【推导】 */
                part combustor : '部件定义'::'Combustor';
                doc /* 生命线：燃烧室。【推导】 */

                message m1 from healthMonitor to fadec;
                doc /* 消息 m1：健康监测模块向 FADEC 发送 DegradationDetected 事件。来源转换：running → degraded。【推导】 */
                message m2 from fadec to fadec;
                doc /* 消息 m2：FADEC 内部限制可用推力。来源转换：running → degraded。【推导】 */
                message m3 from fadec to fadec;
                doc /* 消息 m3：FADEC 判断故障可恢复（守卫：recoverable）。来源转换：degraded → relighting。【推导】 */
                message m4 from fadec to combustor;
                doc /* 消息 m4：FADEC 向燃烧室发送 RelightRequested 事件（守卫：relightPermitted）。来源转换：relighting → running。【推导】 */
                message m5 from combustor to fadec;
                doc /* 消息 m5：燃烧室向 FADEC 反馈 RecoveryConfirmed 事件。来源转换：relighting → running。【推导】 */
            }

            /* --- 场景 4：正常与紧急停车 --- */
            interaction def '正常与紧急停车' {
                doc /* 正常与紧急停车场景：各状态 → shuttingDown → off。【推导】 */

                part aircraft : '参与者定义'::'飞机';
                doc /* 生命线：飞机。【推导】 */
                part fadec : '部件定义'::'FADEC';
                doc /* 生命线：FADEC。【推导】 */
                part fuel : '部件定义'::'Fuel';
                doc /* 生命线：燃油系统。【推导】 */

                /* 正常停车 */
                message m1 from aircraft to fadec;
                doc /* 消息 m1：飞机向 FADEC 发送 StopRequested 事件。来源转换：running → shuttingDown。【推导】 */
                message m2 from fadec to fuel;
                doc /* 消息 m2：FADEC 向燃油系统发送切断燃油指令。来源转换：shuttingDown → off。【推导】 */
                message m3 from fuel to fadec;
                doc /* 消息 m3：燃油系统反馈燃油已切断。来源转换：shuttingDown → off。【推导】 */
                message m4 from fadec to fadec;
                doc /* 消息 m4：FADEC 确认 RotorStopped 事件（守卫：coolDownComplete）。来源转换：shuttingDown → off。【推导】 */

                /* 紧急停车 */
                message m5 from aircraft to fadec;
                doc /* 消息 m5：飞机向 FADEC 发送 EmergencyStopRequested 事件。来源转换：任意运行状态 → shuttingDown。【推导】 */
                message m6 from fadec to fuel;
                doc /* 消息 m6：FADEC 向燃油系统发送紧急切断燃油指令。来源转换：shuttingDown → off。【推导】 */
            }

            /* --- 场景 5：起动中止 --- */
            interaction def '起动中止' {
                doc /* 起动中止场景：StartAborted / StartTimedOut → shuttingDown。【推导】 */

                part fadec : '部件定义'::'FADEC';
                doc /* 生命线：FADEC。【推导】 */
                part fuel : '部件定义'::'Fuel';
                doc /* 生命线：燃油系统。【推导】 */

                message m1 from fadec to fadec;
                doc /* 消息 m1：FADEC 检测到 StartAborted 事件。来源转换：cranking/lighting → shuttingDown。【推导】 */
                message m2 from fadec to fuel;
                doc /* 消息 m2：FADEC 向燃油系统发送切断燃油指令。来源转换：shuttingDown → off。【推导】 */
                message m3 from fadec to fadec;
                doc /* 消息 m3：FADEC 检测到 StartTimedOut 事件。来源转换：cranking/lighting → shuttingDown。【推导】 */
                message m4 from fadec to fuel;
                doc /* 消息 m4：FADEC 向燃油系统发送切断燃油指令。来源转换：shuttingDown → off。【推导】 */
            }
        }

        view '发动机级时序图' {
            expose 'P6 时序图'::'事件定义'::'StartRequested';
            expose 'P6 时序图'::'事件定义'::'LightOffConfirmed';
            expose 'P6 时序图'::'事件定义'::'IdleReached';
            expose 'P6 时序图'::'事件定义'::'AccelerationRequested';
            expose 'P6 时序图'::'事件定义'::'TargetReached';
            expose 'P6 时序图'::'事件定义'::'DecelerationRequested';
            expose 'P6 时序图'::'事件定义'::'StopRequested';
            expose 'P6 时序图'::'事件定义'::'EmergencyStopRequested';
            expose 'P6 时序图'::'事件定义'::'DegradationDetected';
            expose 'P6 时序图'::'事件定义'::'RecoveryConfirmed';
            expose 'P6 时序图'::'事件定义'::'RelightRequested';
            expose 'P6 时序图'::'事件定义'::'RotorStopped';
            expose 'P6 时序图'::'事件定义'::'StartAborted';
            expose 'P6 时序图'::'事件定义'::'StartTimedOut';
            expose 'P6 时序图'::'守卫定义'::'startPermitted';
            expose 'P6 时序图'::'守卫定义'::'lightOffValid';
            expose 'P6 时序图'::'守卫定义'::'idleStable';
            expose 'P6 时序图'::'守卫定义'::'recoverable';
            expose 'P6 时序图'::'守卫定义'::'relightPermitted';
            expose 'P6 时序图'::'守卫定义'::'coolDownComplete';
            expose 'P6 时序图'::'场景路径'::'正常起动';
            expose 'P6 时序图'::'场景路径'::'减速';
