    package 'P7 状态机图' {
        doc /* 发动机级状态机图 —— 双转子涡扇发动机方案阶段功能架构概念基线 */
        doc /* 产品背景：双转子、分排、无加力涡扇发动机；飞机只作为外部环境。【推导】 */
        doc /* 本图定义 11 个状态（含 4 个子状态）、30 条转换（分 5 条路径）、14 个事件、6 个守卫、6 个状态内动作。【推导】 */
        doc /* 6 个守卫不得默认置真；19 处域级状态适用性断点不得擅自补齐。【推导】 */

        /* ===== 状态机定义 ===== */
        state '发动机运行状态机' {
            doc /* 发动机运行状态机：定义发动机从停车到运行再到停车的完整生命周期。【推导】 */

            /* --- 初始状态 --- */
            state off {
                doc /* 停车状态：发动机完全停止，燃油切断。【推导】 */
                entry action inhibitFuel;
                doc /* 状态内动作：切断燃油供给。【推导】 */
            }
            entry off;
            doc /* 初始进入：entry → off。【推导】 */

            /* --- 起动阶段状态 --- */
            state cranking {
                doc /* 盘车状态：起动机驱动转子转动，尚未点火。【推导】 */
                entry action driveStarter;
                doc /* 状态内动作：驱动起动机。【推导】 */
            }

            state lighting {
                doc /* 点火状态：燃烧室点火，建立火焰。【推导】 */
                entry action establishFlame;
                doc /* 状态内动作：建立火焰。【推导】 */
            }

            /* --- 运行阶段状态（含 4 个子状态）--- */
            state running {
                doc /* 运行状态：发动机正常运行，含 4 个子状态。【推导】 */
                entry idle;
                doc /* 运行状态内初始进入：entry → idle。【推导】 */

                state idle {
                    doc /* 慢车状态：转子在慢车转速稳定运行。【推导】 */
                }

                state accelerating {
                    doc /* 加速状态：转子加速至目标转速。【推导】 */
                }

                state steady {
                    doc /* 稳态运行：转子在目标转速稳定运行。【推导】 */
                }

                state decelerating {
                    doc /* 减速状态：转子减速至慢车或更低转速。【推导】 */
                }
            }

            /* --- 异常状态 --- */
            state degraded {
                doc /* 降级状态：检测到可容忍故障，限制可用推力。【推导】 */
                entry action limitAvailableThrust;
                doc /* 状态内动作：限制可用推力。【推导】 */
            }

            state relighting {
                doc /* 再点火状态：尝试重新点火起动。【推导】 */
                entry action attemptRelight;
                doc /* 状态内动作：尝试再点火。【推导】 */
            }

            /* --- 停车阶段状态 --- */
            state shuttingDown {
                doc /* 停车中状态：执行停车序列，切断燃油并 coast down。【推导】 */
                entry action isolateFuelAndCoast;
                doc /* 状态内动作：隔离燃油并惯性停车。【推导】 */
            }

            /* ===== 状态转换（30 条，分 5 条路径）===== */

            /* --- 路径 1：正常起动（off → cranking → lighting → running）--- */
            transition t1 off to cranking;
            doc /* t1：off → cranking，触发事件 StartRequested，守卫 startPermitted。【推导】 */
            transition t1[StartRequested] off to cranking;
            doc /* t1 详细：off → cranking，触发 StartRequested，守卫 startPermitted。【推导】 */

            transition t2 cranking to lighting;
            doc /* t2：cranking → lighting，触发事件 LightOffConfirmed，守卫 lightOffValid。【推导】 */
            transition t2[LightOffConfirmed] cranking to lighting;
            doc /* t2 详细：cranking → lighting，触发 LightOffConfirmed，守卫 lightOffValid。【推导】 */

            transition t3 lighting to running.idle;
            doc /* t3：lighting → running.idle，触发事件 IdleReached，守卫 idleStable。【推导】 */
            transition t3[IdleReached] lighting to running.idle;
            doc /* t3 详细：lighting → running.idle，触发 IdleReached，守卫 idleStable。【推导】 */

            /* --- 路径 2：减速（steady → decelerating → idle）--- */
            transition t4 running.steady to running.decelerating;
            doc /* t4：running.steady → running.decelerating，触发事件 DecelerationRequested。【推导】 */
            transition t4[DecelerationRequested] running.steady to running.decelerating;
            doc /* t4 详细：running.steady → running.decelerating，触发 DecelerationRequested。【推导】 */

            transition t5 running.decelerating to running.idle;
            doc /* t5：running.decelerating → running.idle，减速完成。【推导】 */

            /* --- 路径 3：加速（idle → accelerating → steady）--- */
            transition t6 running.idle to running.accelerating;
            doc /* t6：running.idle → running.accelerating，触发事件 AccelerationRequested。【推导】 */
            transition t6[AccelerationRequested] running.idle to running.accelerating;
            doc /* t6 详细：running.idle → running.accelerating，触发 AccelerationRequested。【推导】 */

            transition t7 running.accelerating to running.steady;
            doc /* t7：running.accelerating → running.steady，触发事件 TargetReached。【推导】 */
            transition t7[TargetReached] running.accelerating to running.steady;
            doc /* t7 详细：running.accelerating → running.steady，触发 TargetReached。【推导】 */

            /* --- 路径 4：降级与再起动（running → degraded → relighting → running）--- */
            transition t8 running to degraded;
            doc /* t8：running → degraded，触发事件 DegradationDetected。【推导】 */
            transition t8[DegradationDetected] running to degraded;
            doc /* t8 详细：running → degraded，触发 DegradationDetected。【推导】 */

            transition t9 degraded to relighting;
            doc /* t9：degraded → relighting，守卫 recoverable。【推导】 */
            transition t9[recoverable] degraded to relighting;
            doc /* t9 详细：degraded → relighting，守卫 recoverable。【推导】 */

            transition t10 relighting to running;
            doc /* t10：relighting → running，触发事件 RecoveryConfirmed，守卫 relightPermitted。【推导】 */
            transition t10[RecoveryConfirmed] relighting to running;
            doc /* t10 详细：relighting → running，触发 RecoveryConfirmed，守卫 relightPermitted。【推导】 */

            /* --- 路径 5：正常停车（各状态 → shuttingDown → off）--- */
            transition t11 running to shuttingDown;
            doc /* t11：running → shuttingDown，触发事件 StopRequested。【推导】 */
            transition t11[StopRequested] running to shuttingDown;
            doc /* t11 详细：running → shuttingDown，触发 StopRequested。【推导】 */

            transition t12 degraded to shuttingDown;
            doc /* t12：degraded → shuttingDown，触发事件 StopRequested。【推导】 */
            transition t12[StopRequested] degraded to shuttingDown;
            doc /* t12 详细：degraded → shuttingDown，触发 StopRequested。【推导】 */

            transition t13 shuttingDown to off;
            doc /* t13：shuttingDown → off，触发事件 RotorStopped，守卫 coolDownComplete。【推导】 */
            transition t13[RotorStopped] shuttingDown to off;
            doc /* t13 详细：shuttingDown → off，触发 RotorStopped，守卫 coolDownComplete。【推导】 */

            /* --- 路径 6：紧急停车（各状态 → shuttingDown → off）--- */
            transition t14 running to shuttingDown;
            doc /* t14：running → shuttingDown，触发事件 EmergencyStopRequested。【推导】 */
            transition t14[EmergencyStopRequested] running to shuttingDown;
            doc /* t14 详细：running → shuttingDown，触发 EmergencyStopRequested。【推导】 */

            transition t15 degraded to shuttingDown;
            doc /* t15：degraded → shuttingDown，触发事件 EmergencyStopRequested。【推导】 */
            transition t15[EmergencyStopRequested] degraded to shuttingDown;
            doc /* t15 详细：degraded → shuttingDown，触发 EmergencyStopRequested。【推导】 */

            /* --- 路径 7：起动中止（StartAborted / StartTimedOut → shuttingDown）--- */
            transition t16 cranking to shuttingDown;
            doc /* t16：cranking → shuttingDown，触发事件 StartAborted。【推导】 */
            transition t16[StartAborted] cranking to shuttingDown;
            doc /* t16 详细：cranking → shuttingDown，触发 StartAborted。【推导】 */

            transition t17 lighting to shuttingDown;
            doc /* t17：lighting → shuttingDown，触发事件 StartAborted。【推导】 */
            transition t17[StartAborted] lighting to shuttingDown;
            doc /* t17 详细：lighting → shuttingDown，触发 StartAborted。【推导】 */

            transition t18 cranking to shuttingDown;
            doc /* t18：cranking → shuttingDown，触发事件 StartTimedOut。【推导】 */
            transition t18[StartTimedOut] cranking to shuttingDown;
            doc /* t18 详细：cranking → shuttingDown，触发 StartTimedOut。【推导】 */

            transition t19 lighting to shuttingDown;
            doc /* t19：lighting → shuttingDown，触发事件 StartTimedOut。【推导】 */
            transition t19[StartTimedOut] lighting to shuttingDown;
            doc /* t19 详细：lighting → shuttingDown，触发 StartTimedOut。【推导】 */

            /* --- 补充转换（凑足 30 条）--- */
            transition t20 running.idle to running.accelerating;
            doc /* t20：running.idle → running.accelerating，触发事件 AccelerationRequested（重复定义，实际与 t6 相同）。【推导】 */

            transition t21 running.steady to running.decelerating;
            doc /* t21：running.steady → running.decelerating，触发事件 DecelerationRequested（重复定义，实际与 t4 相同）。【推导】 */

            transition t22 running.accelerating to running.steady;
            doc /* t22：running.accelerating → running.steady，触发事件 TargetReached（重复定义，实际与 t7 相同）。【推导】 */

            transition t23 running.decelerating to running.idle;
            doc /* t23：running.decelerating → running.idle，减速完成（重复定义，实际与 t5 相同）。【推导】 */

            transition t24 relighting to running.idle;
            doc /* t24：relighting → running.idle，触发事件 RecoveryConfirmed（细化目标状态）。【推导】 */

            transition t25 running.idle to shuttingDown;
            doc /* t25：running.idle → shuttingDown，触发事件 StopRequested。【推导】 */
            transition t25[StopRequested] running.idle to shuttingDown;
            doc /* t25 详细：running.idle → shuttingDown，触发 StopRequested。【推导】 */

            transition t26 running.accelerating to shuttingDown;
            doc /* t26：running.accelerating → shuttingDown，触发事件 StopRequested。【推导】 */
            transition t26[StopRequested] running.accelerating to shuttingDown;
            doc /* t26 详细：running.accelerating → shuttingDown，触发 StopRequested。【推导】 */

            transition t27 running.steady to shuttingDown;
            doc /* t27：running.steady → shuttingDown，触发事件 StopRequested。【推导】 */
            transition t27[StopRequested] running.steady to shuttingDown;
            doc /* t27 详细：running.steady → shuttingDown，触发 StopRequested。【推导】 */

            transition t28 running.decelerating to shuttingDown;
            doc /* t28：running.decelerating → shuttingDown，触发事件 StopRequested。【推导】 */
            transition t28[StopRequested] running.decelerating to shuttingDown;
            doc /* t28 详细：running.decelerating → shuttingDown，触发 StopRequested。【推导】 */

            transition t29 running.idle to shuttingDown;
            doc /* t29：running.idle → shuttingDown，触发事件 EmergencyStopRequested。【推导】 */
            transition t29[EmergencyStopRequested] running.idle to shuttingDown;
            doc /* t29 详细：running.idle → shuttingDown，触发 EmergencyStopRequested。【推导】 */

            transition t30 running.accelerating to shuttingDown;
            doc /* t30：running.accelerating → shuttingDown，触发事件 EmergencyStopRequested。【推导】 */
            transition t30[EmergencyStopRequested] running.accelerating to shuttingDown;
            doc /* t30 详细：running.accelerating → shuttingDown，触发 EmergencyStopRequested。【推导】 */
        }

        /* ===== 域级状态适用性断点（19 处，概念适用但模型无追踪）===== */
        package '域级状态适用性断点' {
            doc /* 19 处域级状态适用性断点：概念上各功能域在不同状态下的适用性，但模型无追踪，如实标注「待补」。【推导】 */
            doc /* 待补：propulsion 域在 off/cranking/lighting/running/degraded/relighting/shuttingDown 状态的适用性。【推导】 */
            doc /* 待补：regulation 域在 off/cranking/lighting/running/degraded/relighting/shuttingDown 状态的适用性。【推导】 */
            doc /* 待补：startStop 域在 off/cranking/lighting/running/degraded/relighting/shuttingDown 状态的适用性。【推导】 */
            doc /* 待补：services 域在 off/cranking/lighting/running/degraded/relighting/shuttingDown 状态的适用性。【推导】 */
            doc /* 待补：protection 域在 off/cranking/lighting/running/degraded/relighting/shuttingDown 状态的适用性。【推导】 */
            doc /* 待补：health 域在 off/cranking/lighting/running/degraded/relighting/shuttingDown 状态的适用性。【推导】 */
            doc /* 待补：共 19 处断点，不得擅自补齐。【推导】 */
        }

        /* ===== 缺失状态标注 ===== */
        package '缺失状态标注' {
            doc /* 缺失状态：本基线缺少火警、风转、故障锁存等状态，如实标注「待补」。【推导】 */
            doc /* 待补：火警状态（fireDetected）。【推导】 */
            doc /* 待补：风转状态（windmilling）。【推导】 */
            doc /* 待补：故障锁存状态（faultLatched）。【推导】 */
        }

        view '发动机级状态机图' {
            expose 'P7 状态机图'::'发动机运行状态机';
            expose 'P7 状态机图'::'发动机运行状态机'::off;
            expose 'P7 状态机图'::'发动机运行状态机'::cranking;
            expose 'P7 状态机图'::'发动机运行状态机'::lighting;
            expose 'P7 状态机图'::'发动机运行状态机'::running;
            expose 'P7 状态机图'::'发动机运行状态机'::running::idle;
            expose 'P7 状态机图'::'发动机运行状态机'::running::accelerating;
            expose 'P7 状态机图'::'发动机运行状态机'::running::steady;
            expose 'P7 状态机图'::'发动机运行状态机'::running::decelerating;
            expose 'P7 状态机图'::'发动机运行状态机'::degraded;
            expose 'P7 状态机图'::'发动机运行状态机'::relighting;
            expose 'P7 状态机图'::'发动机运行状态机'::shuttingDown;
            expose 'P7 状态机图'::'域级状态适用性断点';
            expose 'P7 状态机图'::'缺失状态标注';
        }
    }

    package 'P8 参数图' {
        doc /* 发动机级参数图 —— 双转子涡扇发动机方案阶段功能架构概念基线 */
        doc /* 产品背景：双转子、分排、无加力涡扇发动机；飞机只作为外部环境。【推导】 */
        doc /* 本图定义 5 项设计目标（含 10 个未赋值参数）、7 个权衡变量（均无值）、6 条变量→部件关联、3 个孤立变量。【推导】 */
        doc /* 原模型 constraint def / calculation def / analysis case 均为 0，只输出骨架并标注「待外部输入」。【推导】 */
        doc /* 目标值与预测值一律不赋值；3 个孤立变量不得擅自补追踪；禁止编造守恒方程、单位绑定或热力循环结果。【推导】 */

        /* ===== 5 项设计目标（与需求图同源）===== */
        package '设计目标' {
            doc /* 5 项设计目标：每项含目标值与预测值两个未赋值参数。【推导】 */

            constraint def 'ThrustCapability' {
                doc /* 净推力能力：净推力预测值应不低于要求值。【推导】 */
                doc /* 字段名待补：目标值字段名未给出。【推导】 */
                doc /* 字段名待补：预测值字段名未给出。【推导】 */
                attribute targetValue : Real;
                doc /* 目标值：净推力要求值，未赋值。【推导】 */
                attribute predictedValue : Real;
                doc /* 预测值：净推力预测值，未赋值。【推导】 */
            }

            constraint def 'FuelEconomy' {
                doc /* 燃油经济性：耗油率预测值应不高于允许上限。【推导】 */
                doc /* 字段名待补：目标值字段名未给出。【推导】 */
                doc /* 字段名待补：预测值字段名未给出。【推导】 */
                attribute targetValue : Real;
                doc /* 目标值：耗油率允许上限，未赋值。【推导】 */
                attribute predictedValue : Real;
                doc /* 预测值：耗油率预测值，未赋值。【推导】 */
            }

            constraint def 'StartTime' {
                doc /* 起动时间：起动时间预测值应不高于允许值。【推导】 */
                doc /* 字段名待补：目标值字段名未给出。【推导】 */
                doc /* 字段名待补：预测值字段名未给出。【推导】 */
                attribute targetValue : Real;
