    package 'P9 分配矩阵' {
        doc /* 发动机级分配矩阵 —— 双转子涡扇发动机方案阶段功能架构概念基线 */
        doc /* 产品背景：双转子、分排、无加力涡扇发动机；飞机只作为外部环境。【推导】 */
        doc /* 本图定义 49 条 allocate（4 类）、59 条 dependency（4 组）、3 条协同第二承担者。【推导】 */
        doc /* 所有 allocate / dependency 均为匿名 usage 级，无分配类型定义。【推导】 */
        doc /* 口径声明：implements（实现级）为接口追溯唯一真源，affects（影响级）只用于影响分析。【推导】 */

        /* ===== 49 条 allocate（4 类）===== */
        package '分配定义' {
            doc /* 49 条 allocate：定义功能到部件的分配关系。【推导】 */

            /* --- 类 1：复合功能→整机（6 条）--- */
            package '复合功能→整机' {
                doc /* 复合功能→整机：6 个功能域整体分配至整机。【推导】 */

                allocate propulsion to engine;
                doc /* allocate：propulsion 域分配至整机 engine。【推导】 */

                allocate regulation to engine;
                doc /* allocate：regulation 域分配至整机 engine。【推导】 */

                allocate startStop to engine;
                doc /* allocate：startStop 域分配至整机 engine。【推导】 */

                allocate services to engine;
                doc /* allocate：services 域分配至整机 engine。【推导】 */

                allocate protection to engine;
                doc /* allocate：protection 域分配至整机 engine。【推导】 */

                allocate health to engine;
                doc /* allocate：health 域分配至整机 engine。【推导】 */
            }

            /* --- 类 2：叶功能→部件（34 条，按域归并）--- */
            package '叶功能→部件' {
                doc /* 叶功能→部件：34 个叶功能分配至具体部件，按域归并。【推导】 */

                /* propulsion 域（10 条） */
                package 'propulsion 域分配' {
                    doc /* propulsion 域叶功能分配至 10 个部件。【推导】 */
                    allocate captureAir to inlet;
                    doc /* allocate：captureAir 分配至 inlet。【推导】 */
                    allocate compressFan to fan;
                    doc /* allocate：compressFan 分配至 fan。【推导】 */
                    allocate compressHPC to hpc;
                    doc /* allocate：compressHPC 分配至 hpc。【推导】 */
                    allocate burnFuel to combustor;
                    doc /* allocate：burnFuel 分配至 combustor。【推导】 */
                    allocate expandHPT to hpt;
                    doc /* allocate：expandHPT 分配至 hpt。【推导】 */
                    allocate expandLPT to lpt;
                    doc /* allocate：expandLPT 分配至 lpt。【推导】 */
                    allocate expandCoreJet to coreNozzle;
                    doc /* allocate：expandCoreJet 分配至 coreNozzle。【推导】 */
                    allocate expandBypassJet to bypassNozzle;
                    doc /* allocate：expandBypassJet 分配至 bypassNozzle。【推导】 */
                    allocate driveHPSpool to hpSpool;
                    doc /* allocate：driveHPSpool 分配至 hpSpool。【推导】 */
                    allocate driveLPSpool to lpSpool;
                    doc /* allocate：driveLPSpool 分配至 lpSpool。【推导】 */
                }

                /* regulation 域（1 条） */
                package 'regulation 域分配' {
                    doc /* regulation 域叶功能分配至 fadec。【推导】 */
                    allocate regulateThrust to fadec;
                    doc /* allocate：regulateThrust 分配至 fadec。【推导】 */
                }

                /* startStop 域（2 条） */
                package 'startStop 域分配' {
                    doc /* startStop 域叶功能分配至 fadec 与 starter。【推导】 */
                    allocate initiateStart to fadec;
                    doc /* allocate：initiateStart 分配至 fadec。【推导】 */
                    allocate driveStarter to starter;
                    doc /* allocate：driveStarter 分配至 starter。【推导】 */
                }

                /* services 域（5 条） */
                package 'services 域分配' {
                    doc /* services 域叶功能分配至 5 个部件。【推导】 */
                    allocate supplyFuel to fuel;
                    doc /* allocate：supplyFuel 分配至 fuel。【推导】 */
                    allocate distributeOil to oil;
                    doc /* allocate：distributeOil 分配至 oil。【推导】 */
                    allocate manageThermal to thermal;
                    doc /* allocate：manageThermal 分配至 thermal。【推导】 */
                    allocate extractBleed to bleed;
                    doc /* allocate：extractBleed 分配至 bleed。【推导】 */
                    allocate extractAccessoryPower to gearbox;
                    doc /* allocate：extractAccessoryPower 分配至 gearbox。【推导】 */
                }

                /* protection 域（1 条） */
                package 'protection 域分配' {
                    doc /* protection 域叶功能分配至 fadec。【推导】 */
                    allocate detectFault to fadec;
                    doc /* allocate：detectFault 分配至 fadec。【推导】 */
                }

                /* health 域（2 条） */
                package 'health 域分配' {
                    doc /* health 域叶功能分配至 sensors 与 healthMonitor。【推导】 */
                    allocate acquireSensors to sensors;
                    doc /* allocate：acquireSensors 分配至 sensors。【推导】 */
                    allocate assessHealth to healthMonitor;
                    doc /* allocate：assessHealth 分配至 healthMonitor。【推导】 */
                }
            }

            /* --- 类 3：状态效应动作→部件（6 条）--- */
            package '状态效应动作→部件' {
                doc /* 状态效应动作→部件：6 条状态内动作分配至部件。【推导】 */

                allocate inhibitFuel to fuel;
                doc /* allocate：off 状态 inhibitFuel 动作分配至 fuel。【推导】 */

                allocate driveStarter to starter;
                doc /* allocate：cranking 状态 driveStarter 动作分配至 starter。【推导】 */

                allocate establishFlame to fuel;
                doc /* allocate：lighting 状态 establishFlame 动作分配至 fuel。【推导】 */

                allocate limitAvailableThrust to fadec;
                doc /* allocate：degraded 状态 limitAvailableThrust 动作分配至 fadec。【推导】 */

                allocate attemptRelight to fadec;
                doc /* allocate：relighting 状态 attemptRelight 动作分配至 fadec。【推导】 */

                allocate isolateFuelAndCoast to fuel;
                doc /* allocate：shuttingDown 状态 isolateFuelAndCoast 动作分配至 fuel。【推导】 */
            }

            /* --- 类 4：协同第二承担者（3 条）--- */
            package '协同第二承担者' {
                doc /* 协同第二承担者：3 条功能由第二承担者协同完成，必须保留。【推导】 */

                allocate sequenceStop to fuel;
                doc /* allocate：sequenceStop 功能由 fuel 作为第二承担者协同完成。【推导】 */

                allocate commandProtectiveResponse to fuel;
                doc /* allocate：commandProtectiveResponse 功能由 fuel 作为第二承担者协同完成。【推导】 */

                allocate extractAccessoryPower to generator;
                doc /* allocate：extractAccessoryPower 功能由 generator 作为第二承担者协同完成。【推导】 */
            }
        }

        /* ===== 59 条 dependency（4 组）===== */
        package '追踪定义' {
            doc /* 59 条 dependency：定义需求、状态、功能域、变量之间的追踪关系。【推导】 */
            doc /* 口径声明：dependency 仅追踪不执行。【推导】 */

            /* --- 组 1：需求→功能域（6 条）--- */
            package '需求→功能域' {
                doc /* 需求→功能域：5 条需求分配至 4 个功能域，共 6 条追踪。【推导】 */

                dependency ThrustCapability to propulsion;
                doc /* dependency：ThrustCapability 需求追踪至 propulsion 域。【推导】 */

                dependency FuelEconomy to propulsion;
                doc /* dependency：FuelEconomy 需求追踪至 propulsion 域。【推导】 */

                dependency FuelEconomy to regulation;
                doc /* dependency：FuelEconomy 需求追踪至 regulation 域。【推导】 */

                dependency StartTime to startStop;
                doc /* dependency：StartTime 需求追踪至 startStop 域。【推导】 */

                dependency Operability to regulation;
                doc /* dependency：Operability 需求追踪至 regulation 域。【推导】 */

                dependency ProtectionLatency to protection;
                doc /* dependency：ProtectionLatency 需求追踪至 protection 域。【推导】 */
            }

            /* --- 组 2：状态→功能域（11 条）--- */
            package '状态→功能域' {
                doc /* 状态→功能域：11 个状态追踪至相关功能域。【推导】 */

                dependency off to propulsion;
                doc /* dependency：off 状态追踪至 propulsion 域。【推导】 */

                dependency cranking to startStop;
                doc /* dependency：cranking 状态追踪至 startStop 域。【推导】 */

                dependency lighting to startStop;
                doc /* dependency：lighting 状态追踪至 startStop 域。【推导】 */

                dependency running to propulsion;
                doc /* dependency：running 状态追踪至 propulsion 域。【推导】 */

                dependency running to regulation;
                doc /* dependency：running 状态追踪至 regulation 域。【推导】 */

                dependency degraded to protection;
                doc /* dependency：degraded 状态追踪至 protection 域。【推导】 */

                dependency relighting to startStop;
                doc /* dependency：relighting 状态追踪至 startStop 域。【推导】 */

                dependency shuttingDown to startStop;
                doc /* dependency：shuttingDown 状态追踪至 startStop 域。【推导】 */

                dependency shuttingDown to services;
                doc /* dependency：shuttingDown 状态追踪至 services 域。【推导】 */

                dependency idle to regulation;
                doc /* dependency：idle 子状态追踪至 regulation 域。【推导】 */

                dependency steady to regulation;
                doc /* dependency：steady 子状态追踪至 regulation 域。【推导】 */
            }

            /* --- 组 3：功能域→接口（36 条）--- */
            package '功能域→接口' {
                doc /* 功能域→接口：6 个功能域追踪至 31 条内部接口 + 5 条边界委托，共 36 条追踪。【推导】 */

                /* propulsion 域→接口（11 条） */
                dependency propulsion to I01;
                doc /* dependency：propulsion 域追踪至 I01 接口。【推导】 */
                dependency propulsion to I02;
                doc /* dependency：propulsion 域追踪至 I02 接口。【推导】 */
                dependency propulsion to I03;
                doc /* dependency：propulsion 域追踪至 I03 接口。【推导】 */
                dependency propulsion to I04;
                doc /* dependency：propulsion 域追踪至 I04 接口。【推导】 */
                dependency propulsion to I05;
                doc /* dependency：propulsion 域追踪至 I05 接口。【推导】 */
                dependency propulsion to I06;
                doc /* dependency：propulsion 域追踪至 I06 接口。【推导】 */
                dependency propulsion to I07;
                doc /* dependency：propulsion 域追踪至 I07 接口。【推导】 */
                dependency propulsion to I11;
                doc /* dependency：propulsion 域追踪至 I11 接口。【推导】 */
                dependency propulsion to I12;
                doc /* dependency：propulsion 域追踪至 I12 接口。【推导】 */
                dependency propulsion to I13;
                doc /* dependency：propulsion 域追踪至 I13 接口。【推导】 */
                dependency propulsion to I14;
                doc /* dependency：propulsion 域追踪至 I14 接口。【推导】 */

                /* regulation 域→接口（6 条） */
                dependency regulation to I25;
                doc /* dependency：regulation 域追踪至 I25 接口。【推导】 */
                dependency regulation to I26;
                doc /* dependency：regulation 域追踪至 I26 接口。【推导】 */
                dependency regulation to I27;
                doc /* dependency：regulation 域追踪至 I27 接口。【推导】 */
                dependency regulation to I28;
                doc /* dependency：regulation 域追踪至 I28 接口。【推导】 */
                dependency regulation to I29;
                doc /* dependency：regulation 域追踪至 I29 接口。【推导】 */
                dependency regulation to demand;
                doc /* dependency：regulation 域追踪至 demand 边界端口。【推导】 */

                /* startStop 域→接口（4 条） */
                dependency startStop to I15;
                doc /* dependency：startStop 域追踪至 I15 接口。【推导】 */
                dependency startStop to I29;
                doc /* dependency：startStop 域追踪至 I29 接口。【推导】 */
                dependency startStop to aircraftElectric;
                doc /* dependency：startStop 域追踪至 aircraftElectric 边界端口。【推导】 */
                dependency startStop to controlStatus;
                doc /* dependency：startStop 域追踪至 controlStatus 边界端口。【推导】 */

                /* services 域→接口（8 条） */
                dependency services to I08;
                doc /* dependency：services 域追踪至 I08 接口。【推导】 */
                dependency services to I10;
                doc /* dependency：services 域追踪至 I10 接口。【推导】 */
                dependency services to I16;
                doc /* dependency：services 域追踪至 I16 接口。【推导】 */
                dependency services to I17;
                doc /* dependency：services 域追踪至 I17 接口。【推导】 */
                dependency services to I18;
                doc /* dependency：services 域追踪至 I18 接口。【推导】 */
                dependency services to I19;
                doc /* dependency：services 域追踪至 I19 接口。【推导】 */
                dependency services to I20;
                doc /* dependency：services 域追踪至 I20 接口。【推导】 */
                dependency services to I21;
                doc /* dependency：services 域追踪至 I21 接口。【推导】 */

                /* protection 域→接口（3 条） */
                dependency protection to I25;
                doc /* dependency：protection 域追踪至 I25 接口。【推导】 */
                dependency protection to I27;
                doc /* dependency：protection 域追踪至 I27 接口。【推导】 */
                dependency protection to healthStatus;
                doc /* dependency：protection 域追踪至 healthStatus 边界端口。【推导】 */

                /* health 域→接口（4 条） */
                dependency health to I25;
                doc /* dependency：health 域追踪至 I25 接口。【推导】 */
                dependency health to I26;
                doc /* dependency：health 域追踪至 I26 接口。【推导】 */
                dependency health to healthStatus;
                doc /* dependency：health 域追踪至 healthStatus 边界端口。【推导】 */
                dependency health to rejectedHeat;
                doc /* dependency：health 域追踪至 rejectedHeat 边界端口。【推导】 */
            }

            /* --- 组 4：变量→部件（6 条）--- */
            package '变量→部件' {
                doc /* 变量→部件：7 个权衡变量中 4 个追踪至部件，共 6 条追踪。【推导】 */

                dependency bypassRatio to fan;
