        decide 'ODD判断';
        if '校验ODD条件' then '下发压缩机转速指令';
        if not '校验ODD条件' then '反馈任务失败';
        fork '并行指令下发';
        succession first '下发压缩机转速指令' then '并行指令下发';
        succession first '下发前阀开度指令' then '并行指令下发';
        succession first '下发后阀开度指令' then '并行指令下发';
        join '指令汇合';
        succession first '并行指令下发' then '执行制冷动作';
        succession first '执行制冷动作' then '回传制冷状态';
        succession first '回传制冷状态' then '反馈任务完成';
    }

